// Interpreta la respuesta de Ollama y la deja lista para Node-RED
const o = $input.first().json;
const texto = o.response || "";
let d = null;
try { d = JSON.parse(texto); }
catch (e) {
  const m = texto.match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = null; } }
}
const lista = (v) => Array.isArray(v) ? v.map(String).slice(0, 5) : (v ? [String(v)] : []);
const diagnostico = d
  ? { resumen: String(d.resumen || ""), alertas: lista(d.alertas), recomendaciones: lista(d.recomendaciones), prediccion_energia: String(d.prediccion_energia || "") }
  : { resumen: "No se pudo interpretar la respuesta del modelo.", alertas: [], recomendaciones: [], prediccion_energia: "", crudo: texto.slice(0, 400) };
return [{ json: {
  ts: Date.now(),
  modelo: o.model || "qwen2.5:3b",
  duracion_s: o.total_duration ? Math.round(o.total_duration / 1e9) : null,
  valido: !!d,
  diagnostico: diagnostico
} }];
